namespace sv_63b41c4150e94b8d89d0cef21f8a1645.Services;

/// <summary>
/// Immutable record cascaded app-wide via CascadingValueSource so that
/// every component—regardless of render mode—can read the current warehouse.
/// </summary>
public record WarehouseState(string WarehouseId, string WarehouseName)
{
    public static readonly WarehouseState Default = new("wh-1", "Warehouse A");

    public static readonly IReadOnlyList<WarehouseState> All =
