@* Interactive so it can handle the change event. Renders inside the static MainLayout. *@
@rendermode InteractiveServer

@using sv_63b41c4150e94b8d89d0cef21f8a1645.Services
@inject CascadingValueSource<WarehouseState> WarehouseSource

<select class="form-select form-select-sm"
        style="width:180px;"
        value="@_selectedId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseState.All)
    {
        <option value="@wh.WarehouseId">@wh.WarehouseName</option>
    }
</select>

@code {
    private string _selectedId = WarehouseState.Default.WarehouseId;

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? WarehouseState.Default.WarehouseId;
        var selected = WarehouseState.All.FirstOrDefault(w => w.WarehouseId == _selectedId)
                       ?? WarehouseState.Default;

        // Push to every [CascadingParameter] subscriber across all render modes.
        await WarehouseSource.NotifyChangedAsync(selected);
    }
}

@* Displays the latest low-stock count from InventoryAlertService.
   Subscribes to OnChange so it updates when ANY component triggers a refresh. *@
@rendermode InteractiveServer
@implements IDisposable

@using sv_63b41c4150e94b8d89d0cef21f8a1645.Services
@inject InventoryAlertService Alerts

@if (Alerts.LastKnownCount > 0)
{
    <span class="badge bg-danger rounded-pill">@Alerts.LastKnownCount</span>
}
else
{
    <span class="badge bg-success rounded-pill">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because the event may fire from a timer thread.
        _handler = () => InvokeAsync(StateHasChanged);
        Alerts.OnChange += _handler;
    }

    public void Dispose()
    {
        Alerts.OnChange -= _handler;
    }
}

