@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable

@using sv_63b41c4150e94b8d89d0cef21f8a1645.Services
@inject InventoryAlertService Alerts

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

@if (_warehouse is not null)
{
    <div class="card mb-4" style="max-width: 28rem;">
        <div class="card-body">
            <h5 class="card-title">@_warehouse.WarehouseName</h5>
            <p class="card-text">
                Low-stock alerts:
                @if (Alerts.LastKnownCount > 0)
                {
                    <span class="badge bg-danger fs-6">@Alerts.LastKnownCount items</span>
                }
                else
                {
                    <span class="badge bg-success fs-6">None</span>
                }
            </p>
            <p class="text-muted small mb-0">
                Polling every 10 seconds. Last update: @_lastRefresh.ToString("T")
            </p>
        </div>
    </div>
}

@code {
    [CascadingParameter]
    private WarehouseState? _warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime _lastRefresh;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes so this component re-renders
        // even if another component triggered the refresh.
        _handler = () => InvokeAsync(StateHasChanged);
        Alerts.OnChange += _handler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Do an initial refresh, then start the polling loop.
            await RefreshAlerts();
            StartPolling();
        }
    }

    protected override async Task OnParametersSetAsync()
    {
        // Warehouse changed via the cascading value — restart polling for the new site.
        if (_warehouse is not null)
        {
            StopPolling();
            await RefreshAlerts();
            StartPolling();
        }
    }

    private async Task RefreshAlerts()
    {
        if (_warehouse is null) return;
        await Alerts.RefreshAsync(_warehouse.WarehouseId);
        _lastRefresh = DateTime.Now;
        // OnChange fires inside RefreshAsync, which triggers StateHasChanged for all subscribers.
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAlerts();
                // StateHasChanged is triggered via OnChange handler above.
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / warehouse switch.
        }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        Alerts.OnChange -= _handler;
        StopPolling();
    }
}

